import { useState, useEffect, useRef } from "react";
import axios from "axios";
import { motion, AnimatePresence } from "framer-motion";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { oneDark } from "react-syntax-highlighter/dist/esm/styles/prism";

export default function App() {
  const [code, setCode] = useState("");
  const [explanation, setExplanation] = useState("");
  const [displayedText, setDisplayedText] = useState("");
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const explanationRef = useRef(null);

  const explainCode = async () => {
  if (!code.trim()) return;

  setLoading(true);
  setExplanation("");
  setDisplayedText("");

  try {
    const res = await axios.post(
      "http://127.0.0.1:8000/explain",
      { code },
      { timeout: 60000 }
    );

    if (res.data && res.data.explanation) {
      setExplanation(res.data.explanation);
    } else if (res.data && res.data.error) {
      setExplanation("AI failed to generate explanation. Try again.");
    } else {
      setExplanation("Unexpected server response.");
    }

  } catch (err) {
    setExplanation("Backend not reachable. Is the server running?");
  }

  setLoading(false);
};


  // Typing effect
  useEffect(() => {
    if (!explanation) return;

    let index = 0;
    setDisplayedText("");

    const interval = setInterval(() => {
      setDisplayedText((prev) => prev + explanation[index]);
      index++;
      if (index >= explanation.length) clearInterval(interval);
    }, 15);

    return () => clearInterval(interval);
  }, [explanation]);

  const copyToClipboard = () => {
    navigator.clipboard.writeText(explanation);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  useEffect(() => {
  if (explanationRef.current) {
    explanationRef.current.scrollTop =
      explanationRef.current.scrollHeight;
  }
}, [displayedText]);

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-slate-900 via-slate-900 to-blue-900 px-6 py-12">

      {/* Background Glow */}
      <div className="absolute inset-0 -z-10">
        <div className="absolute top-20 left-1/2 w-[500px] h-[500px] bg-blue-500/20 blur-[120px] -translate-x-1/2"></div>
      </div>

      {/* Navbar */}
      <nav className="w-full max-w-6xl mx-auto mb-14 flex items-center justify-between">
        <div className="flex items-center gap-2 text-white font-semibold text-lg">
          🤖 <span>AI Code Explainer</span>
        </div>
        <div className="text-slate-400 text-sm">
          Local AI · FastAPI · React
        </div>
      </nav>

      {/* Main Content */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="w-full max-w-4xl mx-auto space-y-10"
      >
        {/* Hero */}
        <div className="text-center space-y-3">
          <h1 className="text-5xl font-bold text-white tracking-tight">
            AI Code Explainer
          </h1>
          <p className="text-slate-400 max-w-xl mx-auto">
            Paste your code and instantly understand what it does — clearly and step by step.
          </p>
        </div>

        {/* Code Input */}
        <div className="bg-slate-800/80 backdrop-blur rounded-2xl p-6 border border-slate-700 shadow-xl space-y-4">
          <textarea
            className="w-full h-56 bg-transparent text-slate-100 font-mono text-sm outline-none resize-none"
            placeholder="Paste your code here..."
            value={code}
            onChange={(e) => setCode(e.target.value)}
          />

          <div className="flex justify-end">
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={explainCode}
              disabled={loading}
              className="px-6 py-3 rounded-xl bg-blue-500 hover:bg-blue-600 transition text-white font-semibold disabled:opacity-50"
            >
              {loading ? "AI is thinking..." : "Explain Code"}
            </motion.button>
          </div>
        </div>

        {/* Explanation */}
        <AnimatePresence>
          {explanation && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.4 }}
              className="bg-slate-800/90 backdrop-blur rounded-2xl p-8 border border-slate-700 shadow-2xl"
            >
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl font-semibold text-white flex items-center gap-2">
                  🧠 Explanation
                </h3>

                <button
                  onClick={copyToClipboard}
                  className="text-sm px-3 py-1 rounded-lg bg-slate-700 hover:bg-slate-600 transition text-white"
                >
                  {copied ? "Copied!" : "Copy"}
                </button>
              </div>

              <SyntaxHighlighter
                language="text"
                style={oneDark}
                customStyle={{
                  background: "transparent",
                  padding: 0,
                  margin: 0,
                }}
              >
                {displayedText}
              </SyntaxHighlighter>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>

      {/* Footer */}
      <footer className="mt-20 text-center text-slate-500 text-sm">
        Built smartly using React, Tailwind & Local AI
      </footer>
    </div>
  );
}
